import React, { useState, useEffect } from 'react';
import axios from 'axios';
// Agar is component ka koi alag CSS file hai, toh usko yahan import kar lena

const PropertyList = () => {
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    // API Call to Spring Boot Backend
    axios.get("http://localhost:8080/api/properties")
      .then(response => {
        setProperties(response.data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Error fetching properties:", err);
        setError("Failed to load properties.");
        setLoading(false);
      });
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "40px" }}><h2>Loading properties...</h2></div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "40px", color: "red" }}><h2>{error}</h2></div>;
  }

  return (
    <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "20px" }}>
      <h2 style={{ textAlign: "center", marginBottom: "30px", color: "#4a3b52", fontSize: "2.2rem" }}>
        Available PGs & Hostels
      </h2>
      
      {/* Grid container for properties */}
      <div style={{ 
        display: "grid", 
        gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", 
        gap: "20px" 
      }}>
        {properties.map((property) => (
          <div key={property.id} style={{
            border: "1px solid #e0e0e0",
            borderRadius: "10px",
            overflow: "hidden",
            boxShadow: "0 4px 8px rgba(0,0,0,0.1)",
            backgroundColor: "#fff",
            display: "flex",
            flexDirection: "column"
          }}>
            
            {/* IMAGE SECTION */}
            <div style={{ width: "100%", height: "200px", backgroundColor: "#f0f0f0" }}>
              <img 
                src={
                  property.photoUrl && property.photoUrl.match(/\.(jpeg|jpg|gif|png)$/) != null 
                    ? property.photoUrl 
                    : "https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=800&q=80"
                } 
                alt={property.pgName || "PG Image"} 
                style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                onError={(e) => {
                  e.target.onerror = null; 
                  e.target.src = "https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=800&q=80";
                }}
              />
            </div>

            {/* DETAILS SECTION */}
            <div style={{ padding: "15px", flex: 1, display: "flex", flexDirection: "column", justifyContent: "space-between" }}>
              <div>
                <h3 style={{ margin: "0 0 10px 0", color: "#333", fontSize: "1.2rem" }}>
                  {property.pgName}
                </h3>
                
                <div style={{ display: "flex", alignItems: "center", marginBottom: "8px", color: "#666" }}>
                  <span style={{ marginRight: "8px" }}>📍</span>
                  <span>{property.city}</span>
                </div>
                
                <div style={{ display: "flex", alignItems: "center", marginBottom: "15px", fontWeight: "bold", color: "#4a154b" }}>
                  <span style={{ marginRight: "8px" }}>💰</span>
                  <span>₹{property.rent}/month</span>
                </div>
              </div>

              {/* ACTION BUTTON */}
              <button style={{ 
                width: '100%', padding: '10px', 
                backgroundColor: '#e6dff0', border: 'none', borderRadius: '5px',
                cursor: 'pointer', fontWeight: 'bold', color: '#4a154b',
                transition: "background-color 0.3s"
              }}
              onMouseOver={(e) => e.target.style.backgroundColor = '#d4c5e3'}
              onMouseOut={(e) => e.target.style.backgroundColor = '#e6dff0'}
              >
                View Details & Book
              </button>
            </div>
            
          </div>
        ))}
      </div>
    </div>
  );
};

export default PropertyList;
